insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 5, '[Então] que o inimigo persiga a minha alma, e a alcance; e pise em terra a minha vida; e faça habitar minha honra no pó. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 6, 'Levanta-te, SENHOR, em tua ira; exalta-te pelos furores de meus opressores; e desperta para comigo; tu mandaste o juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 7, 'Então o ajuntamento de povos te rodeará; portanto volta a te elevar [a ti mesmo] sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 8, 'O SENHOR julgará aos povos; julga-me, SENHOR, conforme a minha justiça, e conforme a sinceridade [que há] em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 9, 'Que tenha fim a maldade dos maus; mas firma ao justo, tu, ó justo Deus, que provas os corações e os sentimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 10, 'Meu escudo [pertence] a Deus, que salva os corretos de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 11, 'Deus é um justo juiz; e um Deus que se ira todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 12, 'Ele afia a espada para aquele que não se arrepende; ele [já] armou e preparou seu arco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 13, 'E para ele [já] preparou armas mortais; suas flechas utilizará contra os perseguidores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 14, 'Eis que [o injusto] está com dores de perversidade; e está em trabalho de parto, e gerará mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 15, 'Ele cavou um poço e o fez fundo; mas caiu na cova [que ele próprio] fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 16, 'Seu trabalho se voltará contra sua [própria] cabeça; e sua violência descerá sobre o topo de sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 7, 17, 'Eu louvarei ao SENHOR conforme sua justiça; cantarei ao nome do SENHOR, o Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 1, 'Salmo de Davi para o regente, com “Gitite”: Ah DEUS, nosso Senhor, quão glorioso é o teu nome sobre toda a terra! Pois tu puseste tua majestade acima dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 2, 'Da boca das crianças, e dos que mamam, tu fundaste força, por causa de teus adversários, para fazer cessar ao inimigo e ao vingador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 3, 'Quando eu vejo teus céus, obra de teus dedos; a lua e as estrelas, que tu preparaste;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 4, 'O que é o homem, para que tu te lembres dele? E [o que é] o filho do homem, para que o visites?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 5, 'E tu o fizeste um pouco menor que os anjos; e com glória e honra tu o coroaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 6, 'Tu o fazes ter controle sobre as obras de tuas mãos; tudo puseste debaixo de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 7, 'Ovelhas e bois, todos eles, e também os animais do campo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 8, 'As aves dos céus, e os peixes do mar; [e] os que passam pelos caminhos dos mares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 8, 9, 'Ó DEUS, nosso Senhor! Quão glorioso é o teu nome sobre toda a terra!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 1, 'Salmo de Davi, para o regente, em “Mute-Laben”: Louvarei a [ti] , SENHOR com todo o meu coração; contarei todas as tuas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 2, 'Em ti eu ficarei contente e saltarei de alegria; cantarei a teu nome, ó Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 3, 'Meus inimigos voltaram para trás; eles caem e perecem diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 4, 'Porque tu fizeste conforme meu direito e minha causa; tu te sentaste no teu tribunal e julgaste com justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 5, 'Severamente repreendeste às nações, destruíste ao perverso; tu tiraste o nome dele para sempre e eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 6, '[Ao] inimigo, as destruições já se acabaram para sempre. E tu arrasaste as cidades, [e] já pereceu sua memória [com] elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 7, 'Mas o SENHOR se sentará [para governar] eternamente; ele já preparou seu trono para julgar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 8, 'Ele mesmo julgará ao mundo com justiça; e corretamente fará justiça aos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 9, 'O SENHOR será um refúgio para o aflito; um refúgio em tempos de angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 10, 'E confiarão em ti os que conhecem o teu nome; porque tu, SENHOR, nunca desamparaste aos que te buscam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 11, 'Cantai ao SENHOR, que habita em Sião! Contai entre os povos as obras dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 12, 'Porque ele investiga os derramamentos de sangue, [e] lembra-se deles; não se esquece do clamor dos que sofrem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 13, 'Tem misericórdia de mim, SENHOR; olha para o meu sofrimento, [causado] pelos que me odeiam; tu, que me levantas [para fora] das portas da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 14, 'Para que eu conte todos os teus louvores nas portas da filha de Sião, [e] me alegre em tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 15, 'As nações se afundaram na cova que elas fizeram; o pé delas ficou preso na rede que esconderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 16, 'O SENHOR foi conhecido [pelo] juízo que fez; o perverso foi enlaçado pelas obras de suas [próprias] mãos. (Higaiom, Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 17, 'Os perversos irão para o Xeol, e todas as nações que se esquecem de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 18, 'Porque o necessitado não será esquecido para sempre; [nem a] esperança dos oprimidos perecerá eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 19, 'Levanta-te, SENHOR, não prevaleça o homem [contra ti] ; sejam julgadas as nações diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 9, 20, 'Põe medo neles, SENHOR; saibam as nações que eles são meros mortais. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 1, 'Por que, SENHOR, tu estás longe? [Por que] tu te escondes em tempos de angústia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 2, 'Com arrogância o perverso persegue furiosamente ao miserável; sejam presos nas ciladas que planejaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 3, 'Pois o perverso se orgulha do desejo de sua alma; ele bendiz ao ganancioso, e blasfema do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 4, 'Pela arrogância de seu rosto o perverso não se importa; Deus não existe em todos as seus pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 5, 'Em todo tempo seus caminhos atormentam; teus juízos [estão] longe do rosto dele, em grande altura; ele sopra furiosamente todos os seus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 6, 'Ele diz em seu coração: Eu nunca serei abalado; porque de geração após geração nunca [sofrerei] mal algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 7, 'Sua boca está cheia de maldição, e de enganos, e de falsidade; debaixo de sua língua há sofrimento e maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 8, 'Eles se sentam [postos] para as ciladas das aldeias; nos esconderijos ele mata ao inocente; seus olhos observam secretamente ao contra o pobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 9, 'Ele arma ciladas no esconderijo, como o leão em seu covil; arma ciladas para roubar ao miserável; rouba ao miserável, trazendo-o em sua rede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 10, 'Ele se encolhe, se agacha, [para que] os pobres caiam em suas armadilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 11, 'Ele diz em seu coração: Deus [já] se esqueceu; [já] escondeu o seu rosto, nunca mais [o] verá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 12, 'Levanta-te, SENHOR Deus, ergue tua mão; não te esqueças dos miseráveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 13, 'Por que o perverso blasfema de Deus? Ele diz eu seu coração que tu nada [lhe] exigirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 14, 'Tu estás [o] vendo; porque tu olhas para o trabalho e o cansaço, para o entregar em tuas mãos; em ti o pobre põe confiança; tu és o que ajuda ao órfão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 15, 'Quebra tu o braço do perverso e do maligno; faz cobrança da maldade dele, [até que] tu aches nada [mais dela] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 16, 'O SENHOR é Rei eterno e para todo o sempre; as nações perecerão de sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 17, 'SENHOR, tu ouviste o desejo dos humildes; tu fortalecerás os seus corações, e teus ouvidos [os] ouvirão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 10, 18, 'Para fazer justiça ao órfão e ao afligido; para que o homem não mais continue a praticar o terror.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 1, 'Salmo de Davi, para o regente: No SENHOR eu confio; como, pois, tu dizeis à minha alma: Fugi para vossa montanha, [como] um pássaro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 2, 'Porque eis que os maus estão armando o arco; eles estão pondo suas flechas na corda, para atirarem às escuras [com elas] aos corretos de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 3, 'Se os fundamentos são destruídos, o que o justo pode fazer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 4, 'O SENHOR está em seu santo Templo, o trono do SENHOR está nos céus; seus olhos observam com atenção; suas pálpebras provam aos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 5, 'O SENHOR prova ao justo; mas sua alma odeia ao perverso e ao que ama a violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 6, 'Sobre os perversos choverá laços, fogo e enxofre; e o pagamento para seu cálice será vento tempestuoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 11, 7, 'Porque o SENHOR [é] justo, [e] ama as justiças; seu rosto presta atenção ao [que é] correto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 1, 'Salmo de Davi, para o regente, com harpa de oito cordas: Salva, SENHOR, porque os bons estão em falta; porque são poucos os fiéis dentre os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 2, 'Cada um fala falsidade ao seu próximo, [com] lábios elogiam falsamente; falam com duas intenções no coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 3, 'Que o SENHOR corte a todos os lábios que falam falsos elogios, [e toda] língua que fala grandes [mentiras] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 4, 'Pois dizem: Com nossa língua prevaleceremos; nossos lábios [são] nossos; que é senhor sobre nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 5, 'O SENHOR diz: Pela opressão aos humildes, pelo gemido dos necessitados, eu agora me levantarei; porei em segurança àquele a quem ele sopra [desejando oprimir] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 6, 'As palavras do SENHOR são palavras puras, [como] prata refinada em forno de barro, purificada sete vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 7, 'Tu, SENHOR, os guardarás; desta geração os livrarás para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 12, 8, 'Os maus andam cercando, enquanto os mais vis dos filhos dos homens são exaltados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 13, 1, 'Salmo de Davi, para o regente: Até quando, SENHOR, te esquecerás de mim? Para sempre? Até quando tu esconderás de mim o teu rosto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 13, 2, 'Até quando refletirei em minha alma, [tendo] tristeza em meu coração o dia todo? Até quando o meu inimigo se levantará contra mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 13, 3, 'Olha [para mim, e] ouve-me, SENHOR meu Deus; ilumina os meus olhos, para que eu não adormeça [na] morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 13, 4, 'Para que meu inimigo não diga: Eu o venci;e meus inimigos se alegrem, se eu vier a cair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 13, 5, 'Mas eu confio em tua bondade; em tua salvação meu coração se alegrará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 13, 6, 'Cantarei ao SENHOR, porque ele tem me feito muito bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 1, 'Salmo de Davi, para o regente: O tolo diz em seu coração: Não há Deus.Eles têm se pervertido, fazem obras abomináveis; não há quem faça o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 2, 'O SENHOR olhou desde os céus para os filhos dos homens, para ver se havia alguém prudente, que buscasse a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 3, 'Todos se desviaram, juntamente se contaminaram; não há quem faça o bem, nem um sequer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 4, 'Será que não têm conhecimento todos os que praticam a maldade? Eles devoram a meu povo [como se] comessem pão, [e] não clamam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 5, 'Ali eles se encherão de medo, porque Deus está com a geração dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 6, 'Vós envergonhais os planos do humilde, mas o SENHOR é o refúgio dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 14, 7, 'Ah, que de Sião venha a salvação de Israel! Quando o SENHOR restaurar o seu povo de seu infortúnio, Jacó jubilará, Israel se alegrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 15, 1, 'Salmo de Davi: SENHOR, quem morará em tua tenda? Quem habitará no monte de tua santidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 15, 2, 'Aquele que anda sinceramente, e pratica a justiça; e com seu coração fala a verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 15, 3, '[Aquele que] não murmura com sua língua; não faz mal ao seu companheiro, nem aceita insulto contra seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 15, 4, 'Em seus olhos despreza à pessoa que é digna de reprovação, mas honra aos que temem ao SENHOR; mantém seu juramento até sob [seu próprio] prejuízo, e não muda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 15, 5, '[Tal pessoa] não empresta seu dinheiro com juros; nem aceita suborno contra o inocente; quem faz isto, nunca se abalará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 1, 'Cântico de Davi: Guarda-me, ó Deus; porque eu confio em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 2, 'Tu, [minha alma] , disseste ao SENHOR: Tu és meu Senhor; minha bondade não [chega] até ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 3, '[Mas] aos santos que [estão] na terra, e [a] os ilustres, nos quais está todo o meu prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 4, 'As dores se multiplicarão daqueles que se apressam [para servir] a outros [deuses] ; eu não oferecerei seus sacrifícios de derramamento de sangue, e não tomarei seus nomes em meus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 5, 'O SENHOR é a porção da minha herança e o meu cálice; tu sustentas a minha sorte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 6, 'Em lugares agradáveis foram postos os limites [do meu terreno] ; sim, eu recebo uma bela propriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 7, 'Eu louvarei ao SENHOR, que me aconselhou; até de noite meus sentimentos me ensinam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 8, 'Ponho ao SENHOR continuamente diante de mim; porque [ele está] à minha direita; nunca serei abalado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 9, 'Por isso meu coração está contente, e minha glória se alegra; certamente minha carne habitará em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 10, 'Porque tu não deixarás a minha alma no Xeol, nem permitirás que teu Santo veja a degradação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 16, 11, 'Tu me farás conhecer o caminho da vida; fartura de alegrias [há] em tua presença; agrados estão em tua mão direita para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 1, 'Oração de Davi: Ouve, SENHOR, a [minha] justiça; presta atenção ao meu choro, dá ouvidos à minha oração de lábios que não enganam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 2, 'De diante de teu rosto saia o meu julgamento; teus olhos observarão o que é justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 3, 'Tu [já] provaste o meu coração, tu [me] visitaste de noite; tu me investigaste, [e] nada achaste; decidi [que] minha boca não transgredirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 4, 'Quanto às obras dos homens, conforme a palavra de teus lábios eu me guardei dos caminhos do violento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 5, 'Guiando meu andar em teus caminhos, para que meus passos não tropecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 6, 'Eu clamo a ti, ó Deus, porque tu me respondes; inclina teus ouvidos a mim, escuta a minha palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 7, 'Revela maravilhosamente tuas misericórdias, tu salvas aos que confiam [em ti] com tua mão direita daqueles se se levantam contra [ti] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 8, 'Guarda-me como a pupila do olho; esconde-me debaixo da sombra de tuas asas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 9, 'De diante dos perversos que me oprimem; dos meus mortais inimigos que me cercam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 10, 'Eles se enchem de gordura; com sua boca falam arrogantemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 11, 'Agora eles têm nos cercado em nossos passos; eles fixam seus olhos para [nos] derrubar ao chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 12, 'Semelhantes ao leão, que deseja nos despedaçar, e ao leãozinho, que fica em esconderijos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 13, 'Levanta-te, SENHOR, confronta-o, derruba-o; livra minha alma d [as mãos] do perverso com tua espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 14, 'Dos homens com tua mão, SENHOR, dos homens que são do mundo, cuja parte está n [esta] vida, cujo ventre enches de teu secreto [tesouro] ; os filhos se fartam, e deixam sua sobra para suas crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 17, 15, '[Mas] eu olharei para teu rosto em justiça; serei satisfeito de tua semelhança, quando eu despertar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 1, 'Para o regente. Do servo do SENHOR, chamado Davi, o qual falou as palavras deste cântico ao SENHOR, no dia em que o SENHOR o livrou das mãos de todos os seus inimigos, e das mãos de Saul. Ele disse: Eu te amarei, SENHOR, [tu és] minha força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 2, 'O SENHOR é minha rocha, e minha fortaleza, e meu libertador, meu Deus, meu rochedo, em quem confio; [é] meu escudo, e a força da minha salvação, meu alto refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 3, 'Eu clamei ao SENHOR digno de louvor; e fiquei livre de meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 4, 'Cordas de morte me cercaram; e riachos de maldade me encheram de medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 5, 'Cordas do Xeol me envolveram; laços de morte me afrontaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 6, 'Em minha angústia, clamei ao SENHOR, e roguei a meu Deus; desde o seu Templo ele ouviu a minha voz; e o meu clamor diante de seu rosto chegou aos ouvidos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 7, 'Então a terra de abalou e tremeu; e os fundamentos dos montes de moveram e foram abalados, porque ele se irritou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 8, 'Fumaça subiu de seu nariz, e fogo consumidor saiu de sua boca; carvões foram acesos por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 9, 'Ele moveu os céus, e desceu; e as trevas [estavam] debaixo de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 10, 'Ele montou sobre um querubim, e fez seu voo; e voou veloz sobre as assas do vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 11, 'Ele pôs as trevas como seu esconderijo; pôs a sua tenda ao redor dele; trevas das águas, nuvens dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 12, 'Do brilho de sua presença suas nuvens se espalharam, [e também] a saraiva, e as brasas de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 13, 'E o SENHOR trovejou nos céus; e o Altíssimo soltou sua voz; saraiva e brasas de fogo [caíram] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 14, 'Ele mandou suas flechas, e os dispersou; e [lançou] muitos raios, e os perturbou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 15, 'E as profundezas das águas foram vistas, e os fundamentos do mundo foram descobertos por tua repreensão, SENHOR, pelo sopro do vento do teu nariz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 16, 'Desde o alto ele enviou, [e] me tomou; tirou-me de muitas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 17, 'Ele me livrou do meu forte inimigo, e daqueles que me odeiam; porque eles eram mais poderosos do que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 18, 'Eles me confrontaram no dia de minha calamidade; mas o SENHOR ficou junto de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 19, 'Ele me tirou para um lugar amplo; ele me libertou, porque se agradou de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 20, 'O SENHOR me recompensou conforme a minha justiça; conforme a pureza das minhas mãos ele me retribuiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 21, 'Porque eu guardei os caminhos do SENHOR; nem me [afastei] do meu Deus praticando o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 22, 'Porque todos os juízos dele estavam diante de mim; e não rejeitei seus estatutos para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 23, 'Mas eu fui fiel com ele; e tomei cuidado contra minha maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 24, 'Assim o SENHOR me recompensou conforme a minha justiça; conforme a pureza de minhas mãos perante seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 25, 'Com o bondoso tu te mostras bondoso; [e] com o homem fiel tu te mostras fiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 26, 'Com o puro tu te mostras puro; mas com o perverso tu te mostras agressivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 27, 'Porque tu livras ao povo aflito, e humilhas aos olhos que se exaltam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 28, 'Porque tu acendes minha lâmpada; o SENHOR meu Deus ilumina as minhas trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 29, 'Porque contigo eu marcho [contra] um exército; e com meu Deus eu salto um muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 30, 'O caminho de Deus é perfeito; a palavra do SENHOR é refinada; ele [é] escudo para todos os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 31, 'Porque quem é Deus, a não ser o SENHOR? E quem é rocha, a não ser o nosso Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 32, 'Deus [é] o que me veste de força; e o que dá perfeição ao meu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 33, 'Ele faz meus pés como o das cervas; e me põe em meus lugares altos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 34, 'Ele ensina minhas mãos para a guerra, [de modo que] um arco de bronze se quebra em meus braços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 35, 'Também tu me deste o escudo de tua salvação, e tua mão direita me sustentou; e tua mansidão me engrandeceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 36, 'Tu alargaste os meus passos abaixo de mim; e meus pés não vacilaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 37, 'Persegui a meus inimigos, e eu os alcancei; e não voltei até os exterminá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 38, 'Eu os perfurei, que não puderam mais se levantar; caíram debaixo dos meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 39, 'Porque tu me preparaste com força para a batalha; fizeste se curvarem abaixo de mim aqueles que contra mim tinham se levantado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 40, 'E tu me deste a nuca de meus inimigos; destruí aos que me odiavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 41, 'Eles clamaram, mas não havia quem os livrasse; [clamaram até] ao SENHOR, mas ele não lhes respondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 42, 'Então eu os reduzi a pó, como a poeira ao vento; eu os joguei fora como a lama das ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 43, 'Tu me livraste das brigas do povo; tu me puseste como cabeça das nações; o povo que eu não conhecia me serviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 44, 'Ao [me] ouvirem, [logo] me obedeceram; estrangeiros se sujeitaram a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 45, 'Estrangeiros se enfraqueceram; e tremeram de medo desde suas extremidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 46, 'O SENHOR vive, e bendito [seja] minha rocha; e exaltado [seja] o Deus de minha salvação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 47, 'O Deus que dá minha vingança, e sujeita aos povos debaixo de mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 48, 'Aquele que me livra dos meus inimigos; tu também me exaltas sobre aqueles que se levantam contra mim; tu me livras do homem violento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 49, 'Por isso, SENHOR, eu te louvarei entre as nações, e cantarei ao teu Nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 18, 50, 'Que faz grandes as salvações de seu Rei, e pratica a bondade para com o seu ungido, com Davi, e sua semente, para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 1, 'Salmo de Davi, para o regente: Os céus declaram a glória de Deus; e o firmamento anuncia a obra de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 2, 'Dia após dia ele fala; e noite após noite ele mostra sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 3, 'Não há língua, nem palavras, onde não se ouça a voz deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 4, 'Por toda a terra sai sua corda, e suas palavras até o fim do mundo; para o sol ele pôs uma tenda neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 5, 'E ele [é] como o noivo, que sai de sua câmara; [e] se alegra como um homem valente, para correr [seu] caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 6, 'Desde uma extremidade dos céus [é] sua saída, e seu curso até as [outras] extremidades deles; e nada se esconde de seu calor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 7, 'A lei do SENHOR é perfeita, [e] restaura a alma; o testemunho do SENHOR é fiel, [e] da sabedoria aos simples.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 8, 'Os preceitos do SENHOR são corretos, [e] alegram ao coração; o mandamento do SENHOR é puro, [e] ilumina aos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 9, 'O temor ao SENHOR é limpo, [e] permanece para sempre; os juízos do SENHOR são verdade; juntamente são justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 10, '[São] mais desejáveis que ouro, mais do que muito ouro fino; e mais doces que o mel, e o licor de seus favos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 11, 'Também por eles teu servo é advertido; por guardá-los, [há] muita recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 12, 'Quem pode entender [seus próprios] erros? Limpa-me dos que [me] são ocultos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 13, 'Também retém a teu servo de arrogâncias, para que elas não me controlem; então eu serei sincero, e ficarei limpo de grande transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 19, 14, 'Sejam agradáveis as palavras de minha boca, e o pensamento do meu coração, diante de ti, ó SENHOR, minha rocha e meu Libertador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 1, 'Salmo de Davi, para o regente: Que o SENHOR te responda no dia da angústia; o nome do Deus de Jacó te ponha em lugar seguro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 2, 'Que ele envie a ti ajuda desde [seu] santuário; e desde Sião ele te sustenha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 3, 'Que ele se lembre de todas as tuas ofertas, e aceite os teus holocaustos. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 4, 'Que ele de a ti conforme o teu coração, e faça cumprir todo o teu propósito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 5, 'Nós alegraremos muito por tua salvação, e no nome do nosso Deus levantaremos bandeiras; que o SENHOR cumpra todos os teus pedidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 6, 'Agora eu sei que o SENHOR salva a seu ungido; desde os céus de sua santidade ele lhe responderá, com o poder salvador de sua mão direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 7, 'Alguns confiam em carruagens, e outros em cavalos; mas nós nos lembraremos do nome do SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 8, 'Eles se encurvam, e caem; mas nós nos levantamos, e ficamos em pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 20, 9, 'Salva [-nos] ,SENHOR! Que o Rei nos ouça no dia de nosso clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 1, 'Salmo de Davi para o regente: SENHOR, em tua força o rei se alegra; e como ele fica contente com tua salvação!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 2, 'Tu lhe deste o desejo de seu coração; e tu não negaste o pedido de seus lábios. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 3, 'Porque tu foste até ele com bênçãos de bens; tu puseste na cabeça dele uma coroa de ouro fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 4, 'Ele te pediu vida, [e] tu lhe deste; muitos dias, para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 5, 'Grande [é] a honra dele por tua salvação; honra e majestade tu lhe concedeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 6, 'Porque tu o pões em bênçãos para sempre; tu fazes abundante a alegria dele com tua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 7, 'Porque o rei confia no SENHOR; e ele nunca se abalará com a bondade do Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 8, 'Tua mão alcançará a todos o os teus inimigos; tua mão direita encontrará aos que te odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 9, 'Tu os porás como que [num] forno de fogo no tempo [em que se encontrarem] em tua presença; o SENHOR em sua ira os devorará; e fogo os consumirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 10, 'Tu destruirás o fruto deles de [sobre] a terra; e [também] a semente deles dos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 11, 'Porque eles quiseram o mal contra ti; planejaram uma cilada, [mas] não tiveram sucesso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 12, 'Porque tu os porás em fuga; com [tuas flechas] nas cordas tu lhes apontarás no rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 21, 13, 'Exalta-te, SENHOR, em tua força; cantaremos e louvaremos o teu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 1, 'Salmo de Davi para o regente, como em “cerva da manhã”: Deus meu, Deus meu, por que me desamparaste? Longe [estás] de meu livramento [e] das palavras de meu gemido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 2, 'Deus meu, eu clamo de dia, e tu não me respondes; também [clamo] de noite, e não tenho sossego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 3, 'Porém tu és Santo, que habitas [nos] louvores de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 4, 'Nossos pais confiaram em ti; eles confiaram, e tu os livraste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 5, 'Eles clamaram a ti, e escaparam [do perigo] ; eles confiaram em ti, e não foram envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 6, 'Mas eu sou um verme, e não um homem; [sou] humilhado pelos homens, e desprezado pelo povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 7, 'Todos os que me veem zombam de mim; abrem os lábios [e] sacodem a cabeça, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 8, 'Ele confiou no “SENHOR”; [agora] que ele o salve e o liberte; pois se agrada nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 9, 'Tu és o que me tiraste do ventre; [e] o que me deu segurança, [estando eu] junto aos seios de minha mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 10, 'Eu fui lançado sobre ti desde [que saí d] o útero; desde o ventre de minha mãe tu [és] meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 11, 'Não fiques longe de mim, porque a minha angústia está perto; pois não há quem [me] ajude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 12, 'Muitos touros me cercaram; fortes de Basã me rodearam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 13, 'Abriram contra mim suas bocas, [como] leão que despedaça e ruge.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 14, 'Eu me derramei como água, e todos os meus ossos se soltaram uns dos outros; meu coração é como cera, [e] se derreteu por entre meus órgãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 15, 'Minha força se secou como um caco de barro, e minha língua está grudada no céu da boca; e tu me pões no pó da morte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 16, 'Porque cães ficaram ao meu redor; uma multidão de malfeitores me cercou; perfuraram minhas mãos e meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 17, 'Eu poderia contar todos os meus ossos; eles estão [me] olhando, e prestando atenção em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 18, 'Eles repartem entre si minhas roupas; e sobre minha vestimenta eles lançam sortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 19, 'Porém tu, SENHOR, não fiques longe; força minha, apressa-te para me socorrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 20, 'Livra minha alma da espada; [e] minha vida da violência do cão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 21, 'Salva-me da boca do leão; e responde-me dos chifres dos touros selvagens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 22, '[Então] eu contarei teu nome a meus irmãos; no meio da congregação eu te louvarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 23, 'Vós que temeis ao SENHOR, louvai a ele! E vós, de toda a semente de Jacó, glorificai a ele! Prestai culto a ele, vós de toda a semente de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 24, 'Porque ele não desprezou nem abominou a aflição do aflito, nem escondeu seu rosto dele; mas sim, quando [o aflito] clamou, ele [o] ouviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 25, 'Meu louvor será para ti na grande congregação; eu pagarei meus juramentos perante os que o temem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 26, 'Os humilhados comerão, e ficarão fartos; louvarão ao SENHOR aqueles que o buscam; vosso coração viverá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 27, 'Todos os extremos da terra se lembrarão [disso] , e se converterão ao SENHOR; e todas as gerações das nações adorarão diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 28, 'Porque o reino [pertence] ao SENHOR; e ele governa sobre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 29, 'Todos os ricos da terra comerão e adorarão, [e] perante o rosto dele se prostrarão todos os que descem ao pó, e [que] não podem manter viva sua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 30, 'A descendência o servirá; ela será contada ao Senhor, para a geração [seguinte] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 22, 31, 'Chegarão, e anunciarão a justiça dele ao povo que nascer, porque ele [assim] fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 23, 1, 'Salmo de Davi: O SENHOR é meu pastor, nada me faltará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 23, 2, 'Ele me faz deitar em pastos verdes, [e] me leva a águas quietas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 23, 3, 'Ele restaura minha alma, [e] me guia pelos caminhos da justiça por seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 23, 4, 'Ainda que eu venha a andar pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; tua vara e teu cajado me consolam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 23, 5, 'Tu preparas uma mesa diante de mim à vista de meus adversários; unges a minha cabeça com azeite, meu cálice transborda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 23, 6, 'Certamente o bem e a bondade me seguirão todos os dias de minha vida; e habitarei na casa do SENHOR por muitos e muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 1, 'Salmo de Davi: Ao SENHOR [pertence] a terra, e sua plenitude; o mundo, e os que nele habitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 2, 'Porque ele a fundou sobre os mares; e sobre os rios ele a firmou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 3, 'Quem subirá ao monte do SENHOR? E quem ficará de pé no lugar de sua santidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 4, 'Aquele que é limpo de mãos, e puro de coração, que não entrega sua alma para as coisas vãs, nem jura enganosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 5, 'Este receberá a bênção do SENHOR, e a justiça do Deus de sua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 6, 'Esta é a geração dos que o buscam, dos que procuram a tua face: [a geração de] Jacó. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 7, 'Levantai, portas, vossas cabeças; e levantai-vos vós, entradas eternas; para que entre o Rei da Glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 8, 'Quem é o Rei da Glória? O SENHOR forte e poderoso, o SENHOR poderoso na guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 9, 'Levantai, portas, vossas cabeças; e levantai-vos vós, entradas eternas; para que entre o Rei da Glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 24, 10, 'Quem é este Rei da Glória? O SENHOR dos exércitos; ele é o Rei da Glória! (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 1, 'Salmo de Davi: A ti, SENHOR, levanto minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 2, 'Meu Deus, eu confio em ti; não me deixes envergonhado, nem que meus inimigos se alegrem por me [vencerem] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 3, 'Certamente todos os que esperam em ti, nenhum será envergonhado; envergonhados serão os que traem sem motivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 4, 'Tu me fazes conhecer os teus caminhos; ensina-me teus lugares onde se deve andar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 5, 'Guia-me em tua verdade, e ensina-me; porque tu és o Deus de minha salvação; eu espero por ti o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 6, 'Lembra-te, SENHOR, de tuas misericórdias e de tuas bondades; porque elas são desde a eternidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 7, 'Não te lembres dos pecados de minha juventude e das minhas transgressões; [mas sim] , conforme tua misericórdia, lembra-te de mim por tua bondade, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 8, 'O SENHOR é bom e correto; por isso ele ensinará o caminho aos pecadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 9, 'Ele guiará os humildes ao [bom] juízo; e ensinará aos humildes seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 10, 'Todos os caminhos do SENHOR são bondade e verdade, para aqueles que guardam seu pacto e seus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 11, 'Pelo teu nome, SENHOR, perdoa a minha maldade, porque ela é grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 12, 'Qual é o homem que teme ao SENHOR? Ele lhe ensinará o caminho [que] deve escolher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 13, 'Sua alma habitará no bem; e sua semente [isto é, sua descendência] possuirá a terra em herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 14, 'O segredo do SENHOR é para os que o temem; e ele lhes faz conhecer seu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 15, 'Meus olhos [estão] continuamente [voltados] para o SENHOR, porque ele tirará meus pés da rede de caça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 16, 'Olha para mim, e mim, e tem piedade de mim, porque eu estou solitário e miserável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 17, 'As aflições de meu coração têm se multiplicado; tira-me de minhas angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 18, 'Presta atenção para minha miséria e meu cansativo trabalho; e tira todos os meus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 19, 'Presta atenção a meus inimigos, porque eles estão se multiplicando; eles me odeiam com ódio violento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 20, 'Guarda minha alma, e livra-me; não me deixes envergonhado, porque eu confio em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 21, 'Integridade e justiça me guardem, porque eu espero em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 25, 22, 'Ó Deus, resgata Israel de todas as suas angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 1, 'Salmo de Davi: Faze-me justiça, SENHOR, pois eu ando em minha sinceridade; e eu confio no SENHOR, não me abalarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 2, 'Prova-me, SENHOR, e testa-me; examina meus sentimentos e meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 3, 'Porque tua bondade está diante dos meus olhos; e eu ando em tua verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 4, 'Não me sento com homens vãos, nem converso com desonestos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 5, 'Eu odeio a reunião dos malfeitores; e não me sento com os perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 6, 'Lavo minhas mãos em inocência, e ando ao redor do teu altar, SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 7, 'Para que eu declare com voz de louvores, e para contar todas as tuas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 8, 'SENHOR, eu amo a morada de tua Casa, e o lugar onde habita a tua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 9, 'Não juntes minha alma com os pecadores, nem minha vida com homens sanguinários;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 10, 'Nas mãos deles há más intenções; e sua mão direita é cheia de suborno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 11, 'Mas eu ando em minha sinceridade; livra-me e tem piedade de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 26, 12, 'Meu pé está em um caminho plano; louvarei ao SENHOR nas congregações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 1, 'Salmo de Davi: O SENHOR é minha luz e minha salvação; a quem temerei? O SENHOR é a força da minha vida; de quem terei medo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 2, 'Quando os maus chegaram perto de mim, meus adversários e meus inimigos contra mim, para devorarem minha carne; eles mesmos tropeçaram e caíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 3, 'Ainda que um exército me cercasse, eu não temeria; ainda que uma guerra se levantasse contra mim, nisto mantenho confiança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 4, 'Pedi uma coisa ao SENHOR, [e] a ela buscarei: que eu possa morar na casa do SENHOR todos os dias de minha vida, para ver a beleza do SENHOR, e consultá-lo em seu Templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 5, 'Porque no dia mal ele me esconderá em seu abrigo; ele me encobrirá no oculto de sua tenda; [e] me porá sobre as rochas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 6, 'E minha cabeça será exaltada acima de meus inimigos, que estão ao redor de mim; e eu sacrificarei na tenda dele sacrifícios com alta voz; cantarei e louvarei ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 7, 'Ouve, SENHOR, minha voz, [quando] eu clamo; tem piedade de mim, e responde-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 8, 'Ele diz a ti, meu coração: Buscai a minha face.Eu busco a tua face, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 9, 'Não escondas de mim a tua face, nem rejeites a teu servo com ira; tu tens sido meu socorro; não me deixes, nem me desampares, ó Deus de minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 10, 'Porque meu pai e minha mãe me abandonaram, mas o SENHOR me recolherá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 11, 'Ensina-me, SENHOR, o teu caminho; e guia-me pela via correta, por causa dos meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 12, 'Não me entregues à vontade dos meus adversários, porque se levantaram contra mim falsas testemunhas, e também ao que sopra violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 13, 'Se eu não tivesse crido que veria a bondade do SENHOR na terra dos viventes, [certamente já teria perecido] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 27, 14, 'Espera no SENHOR, esforça-te, e ele fortalecerá o teu coração; espera pois ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 1, 'Salmo de Davi: A ti, SENHOR, rocha minha, eu clamo; não te silencies para comigo; para que não [aconteça de, se] tu calares quanto a mim, eu não [me torne] semelhante aos que descem à cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 2, 'Ouve a voz de minhas súplicas, quando eu clamar a ti, ao levantar às minhas mãos ao templo de tua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 3, 'Não me jogues fora com os perversos, nem com os praticantes da maldade, que falam de paz com sem próximo, porém [há] o mal no coração deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 4, 'Dá-lhes conforme as obras deles, e conforme a maldade de seus atos; dá-lhes conforme a obra das mãos deles, retribui-lhes como eles merecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 5, 'Porque eles não dão atenção para os atos do SENHOR, nem para a obra de suas mãos; [então] ele os derrubará e não os edificará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 6, 'Bendito [seja] o SENHOR, porque ele ouviu a voz de minhas súplicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 7, 'O SENHOR [é] a minha força e meu escudo; meu coração confiou nele, e foi socorrido; por isso meu coração salta de alegria; e com meu canto eu o louvarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 8, 'O SENHOR [é] a força deles, e o poder das salvações de seu Ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 28, 9, 'Salva a teu povo, e abençoa a tua herança; e apascenta-os, e levanta-os para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 1, 'Salmo de Davi: Reconhecei ao SENHOR, vós filhos dos poderosos, reconhecei ao SENHOR [sua] glória e força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 2, 'Reconhecei ao SENHOR a glória de seu nome; adorai ao SENHOR na honra da santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 3, 'A voz do SEHOR [percorre por] sobre as águas; o Deus da glória troveja; o SENHOR [está] sobre muitas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 4, 'A voz do SENHOR [é] poderosa; a voz do SENHOR [é] gloriosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 5, 'A voz do SENHOR quebra aos cedros; o SENHOR quebra aos cedros do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 6, 'Ele os faz saltar como bezerros; ao Líbano e a Sírion como a filhotes de bois selvagens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 7, 'A voz do SENHOR faz chamas de fogo se separarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 8, 'A voz do SENHOR faz tremer o deserto; o SENHOR faz tremer o deserto de Cades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 9, 'A voz do SENHOR faz as cervas terem filhotes, e tira a cobertura das florestas; e em seu templo todos falam de [sua] glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 10, 'O SENHOR se sentou sobre as muitas águas [como dilúvio] ; e o SENHOR se sentará como rei para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 29, 11, 'O SENHOR dará força a seu povo; o SENHOR abençoará a seu povo com paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 1, 'Salmo e canção de Davi para a dedicação da casa: Eu te exaltarei, SENHOR, porque tu me levantaste, e fizeste com que meus inimigos não se alegrassem por causa de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 2, 'SENHOR, meu Deus; eu clamei a ti, e tu me curaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 3, 'SENHOR, tu levantaste minha alma do Xeol; preservaste-me a vida, para que eu não descesse à sepultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 4, 'Cantai ao SENHOR, vós [que sois] santos dele, [e] celebrai a memória de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 5, 'Porque sua ira [dura por] um momento; mas seu favor [dura por toda a] vida; o choro fica pela noite, mas a alegria [vem] pela manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 6, 'Eu disse em minha boa situação: Nunca serei abalado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 7, 'SENHOR, pelo teu favor, tu firmaste minha montanha; [mas quando] tu encobriste o teu rosto, fiquei perturbado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 8, 'A ti, DEUS, eu clamei; e supliquei ao SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 9, '[Dizendo] : Que proveito [há] em meu sangue, [ou] em minha descida a cova? Por acaso o pó da terra te louvará, ou anunciará tua fidelidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 10, 'Ouve [-me] , SENHOR, e tem piedade de mim; sê tu, SENHOR, o meu ajudador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 11, 'Tu tornaste meu pranto em dança; tu desamarraste o meu saco [de lamentação] , e me envolveste de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 30, 12, 'Por isso a [minha] glória cantará para ti, e não se calará; SENHOR, Deus meu, para sempre eu te louvarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 1, 'Salmo de Davi, para o regente: Eu confio em ti, SENHOR; não me deixes envergonhado para sempre; livra-me por tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 2, 'Inclina a mim os teus ouvidos, faze-me escapar depressa [do perigo] ; sê tu por minha rocha firme, por casa fortíssima, para me salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 3, 'Porque tu [és] minha rocha e minha fortaleza; guia-me e conduz-me por causa do teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 4, 'Tira-me da rede que me prepararam em segredo, pois tu [és] minha força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 5, 'Em tuas mãos eu confio meu espírito; tu me resgataste, SENHOR, Deus da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 6, 'Odeio os que dedicam sua atenção a coisas vãs [e] enganosas; porém eu confio no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 7, 'Em tua bondade eu me alegrarei e ficarei cheio de alegria, porque tu viste minha situação miserável; tu reconheceste as angústias de minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 8, 'E tu não me entregastes nas mãos do [meu] inimigo; tu puseste meus pés num lugar amplo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 9, 'Tem misericórdia de mim, SENHOR, porque eu estou angustiado; meus olhos, minha alma e meu ventre foram consumidos pelo sofrimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 10, 'Porque minha vida foi destruída pela aflição, e meus anos pelos suspiros; minha força descaiu por minha maldade; e meus ossos se enfraqueceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 11, 'Por causa de todos os meus adversários eu fui humilhado até entre os meus próximos; e fui feito horrível entre os meus conhecidos; os que me veem na rua fogem de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 12, 'No coração [deles] eu fui esquecido, como se [estivesse] morto; me tornei como um vaso destruído.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 13, 'Porque ouvi a murmuração de muitos, temor [há] ao redor; juntamente tramam contra mim, planejam como matar minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 14, 'Mas eu confio em ti, SENHOR, eu te chamo de meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 15, 'Meus tempos estão em tuas mãos; livra-me da mão dos meus inimigos e daqueles que me perseguem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 16, 'Faz brilhar o teu rosto sobre teu servo; salva-me por tua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 17, 'SENHOR, não me deixes envergonhado, pois eu clamo a ti; que os perversos se envergonhem e se calem no Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 18, 'Emudeçam os lábios mentirosos, que falam coisas duras contra o justo, com arrogância e desprezo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 19, 'Como [é] grade a tua bondade, que guardaste para aqueles que te temem! Tu trabalhaste para os que confiam em ti, na presença dos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 20, 'No esconderijo de tua presença tu os escondes das arrogâncias dos homens; em [tua] tenda tu os encobres da rivalidade das línguas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 21, 'Bendito [seja] o SENHOR, pois ele fez maravilhosa sua bondade para comigo, [como] uma cidade segura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 22, 'Eu dizia em minha aflição: Estou cortado de diante de teus olhos.Porém tu ouviste a voz de minhas súplicas quando clamei a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 23, 'Amai ao SENHOR, todos vós santos dele; o SENHOR guarda aos fiéis, e retribui abundantemente ao que usa de arrogância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 31, 24, 'Sede fortes, e ele fortalecerá vosso coração, todos vós que esperais no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 1, 'Instrução de Davi: Bem-aventurado aquele cuja transgressão é perdoada, cujo pecado é encoberto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 2, 'Bem-aventurado o homem a quem o SENHOR não considera a maldade, e em cujo espírito não há engano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 3, 'Enquanto fiquei calado, meus ossos ficaram cada vez mais fracos com meu gemido pelo dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 4, 'Porque de dia e de noite tua mão pesava sobre mim; meu humor ficou seco como no verão. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 5, 'Eu reconheci meu pecado a ti, e não escondi minha maldade. Eu disse: Confessarei ao SENHOR minhas transgressões;E tu perdoaste a maldade do meu pecado. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 6, 'Por isso cada santo deve orar a ti em [todo] tempo que achar; até no transbordar de muitas águas, elas não chegarão a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 7, 'Tu [és] meu esconderijo, tu me guardas da angústia; tu me envolves de canções alegres de liberdade. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 8, 'Eu te instruirei, e de ensinarei o caminho que deves seguir; eu te aconselharei, e [porei] meus olhos em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 9, 'Não sejais como o cavalo [ou] como a mula, que não têm entendimento; cuja boca é presa com o cabresto e o freio, para que não cheguem a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 10, 'O perverso [terá] muitas dores, mas aquele que confia no SENHOR, a bondade o rodeará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 32, 11, 'Alegrai-vos no SENHOR, e enchei de alegria vós justos, e cantai alegremente todos os corretos de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 1, 'Cantai ao SENHOR, vós [que sois] justos; aos corretos convém louvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 2, 'Louvai ao SENHOR com harpa; cantai a ele com alaúde [e] instrumento de dez cordas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 3, 'Cantai-lhe uma canção nova; tocai [instrumento] bem com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 4, 'Porque a palavra do SENHOR é correta; e todas suas obras [são] fiéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 5, 'Ele ama a justiça e o juízo; a terra está cheia da bondade do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 6, 'Pala palavra do SENHOR foram feitos os céus; e todo o seu exército [foi feito] pelo sopro de sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 7, 'Ele junta as águas do mar como se estivessem empilhadas; aos abismos ele põe como depósitos de tesouros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 8, 'Toda a terra, tenha temor ao SENHOR; todos os moradores do mundo prestem reverência a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 9, 'Porque ele falou, [e logo] se fez; ele mandou, [e logo] apareceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 10, 'O SENHOR desfez a intenção das nações; ele destruiu os planos dos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 11, 'O conselho do SENHOR permanece para sempre; as intenções de seu coração [continuam] de geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 12, 'Bem-aventurada [é] a nação em que seu Deus é o SENHOR; o povo que ele escolheu para si por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 13, 'O SENHOR olha desde os céus; ele vê a todos os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 14, 'Desde sua firme morada ele observa a todos os moradores da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 15, 'Ele forma o coração de todos eles; ele avalia todas as obras deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 16, 'O rei não se salva pela grandeza de [seu] exército, nem o valente escapa do perigo pela [sua] muita força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 17, 'O cavalo é falho como segurança, com sua grande força não livra do perigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 18, 'Eis que os olhos do SENHOR [estão] sobre aqueles que o temem, sobre os que esperam pela sua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 19, 'Para livrar a alma deles da morte, e para os manter vivos durante a fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 20, 'Nossa alma espera no SENHOR; ele [é] nossa socorro e nosso escudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 21, 'Porque nele nosso coração se alegra, porque confiamos no nome de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 33, 22, 'Que tua bondade, SENOR, esteja sobre nós, assim como nós esperamos em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 1, 'Salmo de Davi, quando ele mudou seu comportamento perante Abimeleque, que o expulsou, e ele foi embora: Louvarei ao SENHOR em todo tempo; [haverá] louvor a ele continuamente em minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 2, 'Minha alma se orgulhará no SENHOR; os humildes ouvirão, e se alegrarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 3, 'Engrandecei ao SENHOR comigo, e juntos exaltemos o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 4, 'Busquei ao SENHOR. Ele me respondeu, e me livrou de todos os meus temores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 5, 'Os que olham para ele ficam visivelmente alegres, e seus rostos não são envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 6, 'Este miserável clamou, e o SENHOR ouviu; e ele o salvou de todas as suas angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 7, 'O anjo do SENHOR fica ao redor daqueles que o temem, e os livra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 8, 'Experimentai, e vede que o SENHOR é bom; bem-aventurado [é] o homem que confia nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 9, 'Temei ao SENHOR vós, os seus santos; porque nada falta para aqueles que o temem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 10, 'Os filhos dos leões passam necessidades e têm fome; mas os que buscam ao SENHOR não têm falta de bem algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 11, 'Vinde, filhos, ouvi a mim; eu vos ensinarei o temor ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 12, 'Quem é o homem que deseja vida, que ama [viver por muitos] dias, para ver o bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 13, 'Guarda a tua língua do mal, e os teus lábios de falar falsidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 14, 'Desvia-te do mal, e faze o bem; busca a paz, e segue-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 15, 'Os olhos do SENHOR estão sobre os justos, e seus ouvidos [atentos] ao seu clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 16, 'A face do SENHOR está contra aqueles que fazem o mal, para tirar da terra a memória deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 17, 'Os [justos] clamam, e o SENHOR os ouve. Ele os livra de todas as suas angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 18, 'O SENHOR [está] perto daqueles que estão com o coração partido, e sava os aflitos de espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 19, 'Muitas são as adversidades do justo, mas o SENHOR o livra de todas elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 20, 'Ele guarda todos os seus ossos; nenhum deles é quebrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 21, 'O mal matará o perverso, e os que odeiam o justo serão condenados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 34, 22, 'O SENHOR resgata a alma de seus servos, e todos os que nele confiam não receberão condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 1, 'Salmo de Davi: Disputa, SENHOR contra os meus adversários; luta contra os que lutam contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 2, 'Pega os [teus] pequeno e grande escudos, e levanta-te em meu socorro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 3, 'E tira a lança, e fecha [o caminho] ao encontro de meus perseguidores; dize à minha alma: Eu sou tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 4, 'Envergonhem-se, e sejam humilhados os que buscam [matar] a minha alma; tornem-se para trás, e sejam envergonhados os que planejam o mal contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 5, 'Sejam como a palha perante o vento; e que o anjo do SENHOR os remova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 6, 'Que o caminho deles seja escuro e escorregadio; e o anjo do SENHOR os persiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 7, 'Porque sem motivo eles esconderam de mim a cova de sua rede; sem motivo eles cavaram para minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 8, 'Venha sobre ele a destruição sem que ele saiba [de antemão] ; e sua rede, que ele escondeu, que o prenda; que ele, assolado, caia nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 9, 'E minha alma se alegrará no SENHOR; ela se encherá de alegria por sua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 10, 'Todos os meus ossos dirão: SENHOR, quem [é] como tu, que livras ao miserável daquele que é mais forte do que ele, e ao miserável e necessitado, daquele que o rouba?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 11, 'Levantam-se más testemunhas; exigem de mim [coisas] que não sei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 12, 'Ele retribuem o bem com o mal, desolando a minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 13, 'Mas eu, quando ficavam doentes, minha roupa [era] de saco; eu afligia a minha alma com jejuns, e minha oração voltava ao meu seio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 14, 'Eu agia [para com eles] como [para] um amigo [ou] irmão meu; eu andava encurvado, como que de luto pela mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 15, 'Mas quando eu vacilava, eles se alegravam e se reuniam; inimigos se reuniam sem que eu soubesse; eles me despedaçavam [em palavras] ,e não se calavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 16, 'Entre os fingidos zombadores [em] festas, eles rangiam seus dentes por causa de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 17, 'Senhor, até quando tu [somente] observarás? Resgata minha alma das assolações deles; minha única [vida] dos filhos dos leões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 18, 'Assim eu te louvarei na grande congregação; numa grande multidão eu celebrarei a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 19, 'Não se alegrem meus inimigos por causa de mim por um mau motivo, [nem] acenem com os olhos aquele que me odeiam sem motivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 20, 'Porque eles não falam de paz; mas sim, planejam falsidades contra os pacíficos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 21, 'E abrem suas bocas contra mim, dizendo: Ha-ha, nós vimos com nossos [próprios] olhos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 22, 'Tu, SENHOR, tens visto [isso] ; não fiques calado; SENHOR, não fiques longe de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 23, 'Levanta-te e acorda para meu direito, Deus meu, e Senhor meu, para minha causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 24, 'Julga-me conforme a tua justiça, SENHOR meu Deus; e não deixes eles se alegrarem de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 25, 'Não digam eles em seus corações: Ahá, [vencemos] , alma nossa!nem digam: Nós já o devoramos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 26, 'Que eles se envergonhem, e sejam juntamente humilhados os que se alegram pelo meu mal; vistam-se de vergonha e confusão os que se engrandecem contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 27, 'Cantem de alegria e sejam muito contentes os que amam a minha justiça; e continuamente digam: Seja engrandecido o SENHOR, que ama o bem-estar de seu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 35, 28, 'E minha língua falará de tua justiça, louvando a ti o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 1, 'Salmo de Davi, servo do SENHOR, para o regente: A transgressão do perverso diz ao meu coração [que] não há temor a Deus perante seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 2, 'Porque ele é [tão] orgulhoso diante de seus olhos [que não] achar [nem] odiar sua própria maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 3, 'As palavras da boca dele são malícia e falsidade; ele deixou de [fazer] o que é sábio e bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 4, 'Ele planeja maldade em sua cama; fica no caminho que não é bom; não rejeita o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 5, 'SENHOR, tua bondade [alcança] os céus, e tua fidelidade [chega] até as mais altas nuvens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 6, 'Tua justiça é como as montanhas de Deus, teus juízos [como] um grande abismo; tu, SENHOR, guardas [a vida] dos homens e dos animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 7, 'Como é preciosa, SENHOR, a tua bondade! Porque os filhos dos homens se abrigam à sombra de tuas asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 8, 'Eles se fartam da comida de tua casa, e tu lhes dás de beber [do] ribeiro de teus prazeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 9, 'Porque contigo está a fonte da vida; em tua luz vemos a luz [verdadeira] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 10, 'Estende tua bondade sobre os que te conhecem; e tua justiça sobre os corretos de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 11, 'Não venha sobre mim o pé dos arrogantes, e que a não dos perversos não me mova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 36, 12, 'Ali cairão os que praticam a maldade; eles foram lançados, e não podem se levantar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 1, 'Salmo de Davi: Não te irrites com os malfeitores, nem tenhas inveja dos que praticam perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 2, 'Porque assim como a erva, eles logo serão cortados; e como a verdura eles cairão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 3, 'Confia no SENHOR, e faze o bem; habita a terra, e te alimentarás em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 4, 'E agrada-te no SENHOR; e ele te dará os pedidos de teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 5, 'Entrega o teu caminho ao SENHOR; confia nele, e ele agirá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 6, 'e manifestará a tua justiça como a luz, e o teu direito como o sol do meio-dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 7, 'Descansa no SENHOR, e espera nele; não te irrites contra aquele cujo caminho prospera, [nem] com o homem que planeja maldades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 8, 'Detém a ira, abandona o furor; não te irrites de maneira alguma para fazer o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 9, 'Porque os malfeitores serão exterminados; mas os que esperam no SENHOR herdarão a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 10, 'E ainda um pouco, e o perverso não [mais existirá] ; e tu olharás para o lugar dele, e ele não [aparecerá] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 11, 'Mas os mansos herdarão a terra, e se agradarão com muita paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 12, 'O perverso trama contra o justo, e range seus dentes contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 13, 'O Senhor ri dele, porque vê que já vem o dia dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 14, 'O perversos pegarão a espada e armarão seu arco, para abaterem ao miserável e necessitado, para matarem os corretos no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 15, 'Mas sua espada entrará em seus corações, e seus arcos serão quebrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 16, 'O pouco que o justo [tem] é melhor do que a riqueza de muitos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 17, 'Porque os braços dos perversos serão quebrados, mas o SENHOR sustenta os justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 18, 'O SENHOR conhece os dias dos corretos, e a herança deles permanecerá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 19, 'Eles não serão envergonhados no tempo mau, e terão fartura nos dias de fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 20, 'Mas os perversos perecerão, e os inimigos do SENHOR desaparecerão tal como as melhores partes dos cordeiros; eles de desfarão na fumaça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 21, 'O perverso toma emprestado, e paga de volta; mas o justo se compadece e dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 22, 'Porque os que são por ele abençoados herdarão a terra; mas os que são por ele amaldiçoados serão removidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 23, 'Os passos do homem [justo] são preparados pelo SENHOR; e ele tem prazer em seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 24, 'Quando cai, ele não fica derrubado, pois o SENHOR sustenta a sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 25, 'Eu já fui jovem, e já envelheci; mas nunca vi o justo desamparado, nem a sua semente a pedir pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 26, 'O dia todo ele se compadece, e empresta; e sua semente é abençoada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 27, 'Afasta-te do mal, e faze o bem; e faça sua habitação eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 28, 'Porque o SENHOR ama o juízo, e não desampara a seus santos: eles estão guardados para sempre; mas a semente dos perversos será removida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 29, 'Os justos herdarão a terra, e para sempre nela habitarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 30, 'A boca do justo fala de sabedoria, e sua língua fala do [bom] juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 31, 'A Lei de seu Deus [está] em seu coração; seus passos não serão abalados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 32, 'O perverso espia ao justo, e procura matá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 33, '[Mas] o SENHOR não o deixa em suas mãos; nem também o condenará, quando for julgado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 34, 'Espera no SENHOR, guarda o seu caminho, e ele te exaltará, para herdares a terra; tu verás que os perversos serão removidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 35, 'Eu vi ao perverso violento crescer como a árvore verde, natural da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 36, 'Porém ele já foi embora, e eis que ele não [existe mais] ; eu o procurei, e não foi achado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 37, 'Olha ao sincero, e vê o correto; porque o fim de [tal] homem é a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 38, 'Mas os transgressores serão juntamente destruídos; o fim dos perversos será eliminado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 39, 'Porém a salvação dos justos [vem] do SENHOR, [que é] a força deles no tempo de angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 37, 40, 'E o SENHOR os socorrerá, e os livrará; ele os livrará dos perversos, e os salvará, porque nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 1, 'Salmo de Davi, para lembrança: SENHOR, não me repreendas em tua ira, e não me castigues em teu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 2, 'Porque tuas flechas me atingiram, e tua mão pesou sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 3, 'Na minha carne nada [há que esteja] saudável, por causa de tua ira; não há paz em meus ossos por causa do meu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 4, 'Porque minhas maldades ultrapassam minha cabeça; elas [são] como carga pesada demais para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 5, 'Minhas feridas fedem, e estão apodrecidas, por eu ter sido tão tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 6, 'Eu estou perturbado e abatido; ando o dia todo em sofrimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 7, 'Porque meus lombos ardem muito, e nada há que esteja saudável em minha carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 8, 'Estou enfraquecido e despedaçado; eu gemo pelo sofrimento do meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 38, 9, 'SENHOR, todo o meu sofrimento está diante de ti, e meu gemido não te é oculto.')
